  1→package command
  2→
  3→import (
  4→	"errors"
  5→	"io"
  6→	"strings"
  7→
  8→	"github.com/finalappstore/stupidsamba/internal/smb/status"
  9→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
 10→	"github.com/finalappstore/stupidsamba/internal/vfs"
 11→)
 12→
 13→func init() {
 14→	register(wire.CommandSetInfo, true, true, handleSetInfo)
 15→}
 16→
 17→// handleSetInfo 处理 SMB2 SET_INFO（MS-SMB2 §3.3.5.21）。
 18→func handleSetInfo(ctx *Context) error {
 19→	req, err := wire.ParseSetInfoRequest(ctx.Msg)
 20→	if err != nil {
 21→		return status.InvalidParameter
 22→	}
 23→
 24→	open, err := ctx.resolveOpen(req.FileID)
 25→	if err != nil {
 26→		return err
 27→	}
 28→
 29→	switch req.InfoType {
 30→	case wire.InfoTypeFile:
 31→		err = setFileInfo(ctx, open, req)
 32→	case wire.InfoTypeFileSystem:
 33→		// 卷标/卷属性都不可改：共享的容量与标签来自宿主文件系统。
 34→		err = status.AccessDenied
 35→	case wire.InfoTypeSecurity:
 36→		// 授权完全由配置决定（AGENTS.md §1.1 C8），不接受客户端下发的 ACL。
 37→		// 回 ACCESS_DENIED 而不是 NOT_SUPPORTED：Windows 客户端在
 38→		// "属性→安全" 里改权限时，前者会正常提示，后者会弹出诡异错误。
 39→		err = status.AccessDenied
 40→	default:
 41→		err = status.InvalidInfoClass
 42→	}
 43→	if err != nil {
 44→		return err
 45→	}
 46→
 47→	ctx.Out = (&wire.SetInfoResponse{}).Append(ctx.Out)
 48→	return nil
 49→}
 50→
 51→// setFileInfo 处理 InfoType=FILE 的各信息类。
 52→func setFileInfo(ctx *Context, open *Open, req *wire.SetInfoRequest) error {
 53→	if open.IsPipe() {
 54→		// 管道只有 FilePipeInformation 之类，我们不支持修改。
 55→		return status.InvalidInfoClass
 56→	}
 57→	if err := ctx.RequireWritable(); err != nil {
 58→		return err
 59→	}
 60→	h := open.Handle
 61→	if h == nil {
 62→		return status.FileClosed
 63→	}
 64→
 65→	switch req.FileClass() {
 66→	case wire.FileBasicInformation:
 67→		return setBasicInfo(open, h, req.Buffer)
 68→
 69→	case wire.FileEndOfFileInformation:
 70→		return setEndOfFile(open, h, req.Buffer)
 71→
 72→	case wire.FileAllocationInformation:
 73→		return setAllocation(open, h, req.Buffer)
 74→
 75→	case wire.FileDispositionInformation:
 76→		return setDisposition(open, req.Buffer)
 77→
 78→	case wire.FileRenameInformation:
 79→		return setRename(ctx, open, req.Buffer)
 80→
 81→	case wire.FileLinkInformation:
 82→		// 硬链接：VFS 没有这个能力，明确回不支持而不是假装成功。
 83→		return status.NotSupported
 84→
 85→	case wire.FilePositionInformation:
 86→		// SMB2 读写都带显式偏移，句柄没有隐式游标。
 87→		// 客户端（尤其是 Windows）仍会下发它，回成功即可，忽略取值。
 88→		if len(req.Buffer) < 8 {
 89→			return status.InfoLengthMismatch
 90→		}
 91→		return nil
 92→
 93→	case wire.FileModeInformation:
 94→		if len(req.Buffer) < 4 {
 95→			return status.InfoLengthMismatch
 96→		}
 97→		return nil
 98→
 99→	case wire.FileShortNameInformation:
100→		// 我们不维护 8.3 短名。
101→		return status.NotSupported
102→
103→	case wire.FileValidDataLengthInformation:
104→		// 仅对非稀疏文件有意义，且需要 MANAGE_VOLUME 权限。
105→		return status.NotSupported
106→
107→	case wire.FileFullEaInformation:
108→		return status.NotSupported
109→
110→	default:
111→		ctx.Log.Debug("未实现的 set file info class", "class", req.FileClass())
112→		return status.InvalidInfoClass
113→	}
114→}
115→
116→// setBasicInfo 处理 FileBasicInformation（MS-FSCC §2.4.7）。
117→//
118→// 时间字段有三种取值：
119→//   - 0                  —— 不修改；
120→//   - 0xFFFFFFFFFFFFFFFF —— 冻结该时间戳（后续 IO 不再更新），我们按"不修改"处理；
121→//   - 其他               —— 设置为该 FILETIME。
122→//
123→// FileAttributes 为 0 表示不修改属性。
124→func setBasicInfo(open *Open, h vfs.Handle, buf []byte) error {
125→	if len(buf) < wire.FileBasicInfoSize {
126→		return status.InfoLengthMismatch
127→	}
128→	info, err := wire.ParseFileBasicInfo(buf)
129→	if err != nil {
130→		return status.InvalidParameter
131→	}
132→	if open.GrantedAccess&wire.FileWriteAttributes == 0 {
133→		return status.AccessDenied
134→	}
135→
136→	var (
137→		attr vfs.Attr
138→		mask vfs.AttrMask
139→	)
140→	if vfs.FiletimeIsSet(info.CreationTime) {
141→		attr.CreateTime = vfs.FiletimeToTime(info.CreationTime)
142→		mask |= vfs.AttrCreateTime
143→	}
144→	if vfs.FiletimeIsSet(info.LastAccessTime) {
145→		attr.AccessTime = vfs.FiletimeToTime(info.LastAccessTime)
146→		mask |= vfs.AttrAccessTime
147→	}
148→	if vfs.FiletimeIsSet(info.LastWriteTime) {
149→		attr.WriteTime = vfs.FiletimeToTime(info.LastWriteTime)
150→		mask |= vfs.AttrWriteTime
151→	}
152→	if vfs.FiletimeIsSet(info.ChangeTime) {
153→		attr.ChangeTime = vfs.FiletimeToTime(info.ChangeTime)
154→		mask |= vfs.AttrChangeTime
155→	}
156→	if info.FileAttributes != 0 {
157→		attr.FileAttributes = uint32(info.FileAttributes)
158→		mask |= vfs.AttrFileAttributes
159→	}
160→	if mask == 0 {
161→		// 全是"不修改"，客户端只是在探测能力。
162→		return nil
163→	}
164→	if err := h.SetAttr(&attr, mask); err != nil {
165→		return status.FromVFSError(err)
166→	}
167→	return nil
168→}
169→
170→// setEndOfFile 处理 FileEndOfFileInformation（MS-FSCC §2.4.13）：截断或扩展。
171→func setEndOfFile(open *Open, h vfs.Handle, buf []byte) error {
172→	if len(buf) < wire.FileEndOfFileInfoSize {
173→		return status.InfoLengthMismatch
174→	}
175→	eof, err := wire.ParseFileEndOfFileInfo(buf)
176→	if err != nil {
177→		return status.InvalidParameter
178→	}
179→	if eof < 0 {
180→		return status.InvalidParameter
181→	}
182→	if open.IsDir {
183→		return status.InvalidParameter
184→	}
185→	// 改长度算写操作：MS-FSCC 要求 FILE_WRITE_DATA。
186→	if open.GrantedAccess&(wire.FileWriteData|wire.FileAppendData) == 0 {
187→		return status.AccessDenied
188→	}
189→	if err := h.Truncate(eof); err != nil {
190→		return status.FromVFSError(err)
191→	}
192→	return nil
193→}
194→
195→// setAllocation 处理 FileAllocationInformation（MS-FSCC §2.4.4）。
196→//
197→// 语义与 EndOfFile 不同：它只调整**分配**长度。
198→// 收缩到小于当前 EOF 时才需要真的截断；扩大是"预分配提示"，
199→// 交给 VFS 的 AttrAlloc（本地实现会做 fallocate，失败则忽略）。
200→func setAllocation(open *Open, h vfs.Handle, buf []byte) error {
201→	if len(buf) < wire.FileAllocationInfoSize {
202→		return status.InfoLengthMismatch
203→	}
204→	alloc, err := wire.ParseFileAllocationInfo(buf)
205→	if err != nil {
206→		return status.InvalidParameter
207→	}
208→	if alloc < 0 {
209→		return status.InvalidParameter
210→	}
211→	if open.IsDir {
212→		return status.InvalidParameter
213→	}
214→	if open.GrantedAccess&(wire.FileWriteData|wire.FileAppendData) == 0 {
215→		return status.AccessDenied
216→	}
217→
218→	attr, serr := h.Stat()
219→	if serr != nil {
220→		return status.FromVFSError(serr)
221→	}
222→	if alloc < attr.Size {
223→		// 分配长度小于逻辑长度：EOF 必须跟着缩。
224→		if err := h.Truncate(alloc); err != nil {
225→			return status.FromVFSError(err)
226→		}
227→		return nil
228→	}
229→	if err := h.SetAttr(&vfs.Attr{Alloc: alloc}, vfs.AttrAlloc); err != nil {
230→		if errors.Is(err, vfs.ErrNotSupported) {
231→			// 预分配只是优化，后端不支持不算失败。
232→			return nil
233→		}
234→		return status.FromVFSError(err)
235→	}
236→	return nil
237→}
238→
239→// setDisposition 处理 FileDispositionInformation（MS-FSCC §2.4.11）：
240→// 置位表示"关闭时删除"。
241→func setDisposition(open *Open, buf []byte) error {
242→	if len(buf) < wire.FileDispositionInfoSize {
243→		return status.InfoLengthMismatch
244→	}
245→	del, err := wire.ParseFileDispositionInfo(buf)
246→	if err != nil {
247→		return status.InvalidParameter
248→	}
249→	if del {
250→		if open.GrantedAccess&wire.Delete == 0 {
251→			return status.AccessDenied
252→		}
253→		// 非空目录不能删：这里就要拒绝，等到 CLOSE 才发现就来不及回错了
254→		// （CLOSE 的响应里没有位置报告删除失败）。
255→		if open.IsDir {
256→			if err := dirIsEmpty(open); err != nil {
257→				return err
258→			}
259→		}
260→	}
261→	open.SetDeleteOnClose(del)
262→	return nil
263→}
264→
265→// dirIsEmpty 在目录非空时返回 STATUS_DIRECTORY_NOT_EMPTY。
266→func dirIsEmpty(open *Open) error {
267→	h := open.Handle
268→	if h == nil {
269→		return status.FileClosed
270→	}
271→	// 从头扫一条即可判断；扫完后复位枚举状态，避免污染
272→	// 客户端正在进行的 QUERY_DIRECTORY 游标。
273→	entries, err := h.ReadDir("*", true, 1)
274→	open.ResetDirScan()
275→	if err != nil && !errors.Is(err, io.EOF) {
276→		return status.FromVFSError(err)
277→	}
278→	for _, e := range entries {
279→		if e.Name == "." || e.Name == ".." {
280→			continue
281→		}
282→		return status.DirectoryNotEmpty
283→	}
284→	return nil
285→}
286→
287→// setRename 处理 FileRenameInformation（MS-FSCC §2.4.37.2）。
288→func setRename(ctx *Context, open *Open, buf []byte) error {
289→	info, err := wire.ParseFileRenameInfo(buf)
290→	if err != nil {
291→		return status.InvalidParameter
292→	}
293→	if info.RootDirectory != 0 {
294→		// SMB2 里 RootDirectory 必须为 0（MS-FSCC §2.4.37.2）。
295→		return status.InvalidParameter
296→	}
297→	if open.GrantedAccess&wire.Delete == 0 {
298→		return status.AccessDenied
299→	}
300→
301→	dst, terr := renameTarget(info.FileName)
302→	if terr != nil {
303→		return status.ObjectPathSyntaxBad
304→	}
305→	if dst == "" {
306→		return status.ObjectNameInvalid
307→	}
308→	if dst == open.Path {
309→		// 改名到自己：直接成功，别去动文件系统。
310→		return nil
311→	}
312→
313→	fs := ctx.Tree.FS()
314→	if fs == nil {
315→		return status.NetworkNameDeleted
316→	}
317→	if err := fs.Rename(open.Path, dst, info.ReplaceIfExists); err != nil {
318→		return status.FromVFSError(err)
319→	}
320→
321→	// 句柄在改名后仍然有效，后续 QUERY_INFO 要能回新路径。
322→	open.Path = dst
323→	return nil
324→}
325→
326→// renameTarget 把线格式的目标名规范化成共享内相对路径。
327→//
328→// 线格式用反斜杠分隔、相对共享根、不含前导反斜杠（但真实客户端会带，
329→// 所以要容忍）。规范化与越界校验交给 vfs.CleanPath（AGENTS.md §8）。
330→func renameTarget(name string) (string, error) {
331→	name = strings.ReplaceAll(name, "\\", "/")
332→	name = strings.TrimPrefix(name, "/")
333→	if strings.IndexByte(name, ':') >= 0 {
334→		// 带 stream 名的改名（重命名 ADS）我们不支持，拒绝而不是误删主流。
335→		return "", vfs.ErrNotSupported
336→	}
337→	return vfs.CleanPath(name)
338→}
