241→func setDisposition(open *Open, buf []byte) error {
242→	if len(buf) < wire.FileDispositionInfoSize {
243→		return status.InfoLengthMismatch
244→	}
245→	del, err := wire.ParseFileDispositionInfo(buf)
246→	if err != nil {
247→		return status.InvalidParameter
248→	}
249→	if del {
250→		if open.GrantedAccess&wire.Delete == 0 {
251→			return status.AccessDenied
252→		}
253→		// 非空目录不能删：这里就要拒绝，等到 CLOSE 才发现就来不及回错了
254→		// （CLOSE 的响应里没有位置报告删除失败）。
255→		if open.IsDir {
256→			if err := dirIsEmpty(open); err != nil {
257→				return err
258→			}
259→		}
260→	}
261→	open.SetDeleteOnClose(del)
262→	return nil
263→}
264→
265→// dirIsEmpty 在目录非空时返回 STATUS_DIRECTORY_NOT_EMPTY。
266→func dirIsEmpty(open *Open) error {
267→	h := open.Handle
268→	if h == nil {
269→		return status.FileClosed
270→	}
271→	// 从头扫一条即可判断；扫完后复位枚举状态，避免污染
272→	// 客户端正在进行的 QUERY_DIRECTORY 游标。
273→	entries, err := h.ReadDir("*", true, 1)
274→	open.ResetDirScan()
275→	if err != nil && !errors.Is(err, io.EOF) {
276→		return status.FromVFSError(err)
277→	}
278→	for _, e := range entries {
279→		if e.Name == "." || e.Name == ".." {
280→			continue
281→		}
282→		return status.DirectoryNotEmpty
283→	}
284→	return nil
285→}
286→
287→// setRename 处理 FileRenameInformation（MS-FSCC §2.4.37.2）。
288→func setRename(ctx *Context, open *Open, buf []byte) error {
289→	info, err := wire.ParseFileRenameInfo(buf)
290→	if err != nil {
291→		return status.InvalidParameter
292→	}
293→	if info.RootDirectory != 0 {
294→		// SMB2 里 RootDirectory 必须为 0（MS-FSCC §2.4.37.2）。
295→		return status.InvalidParameter
296→	}
297→	if open.GrantedAccess&wire.Delete == 0 {
298→		return status.AccessDenied
299→	}
300→
301→	dst, terr := renameTarget(info.FileName)
302→	if terr != nil {
303→		return status.ObjectPathSyntaxBad
304→	}
305→	if dst == "" {
306→		return status.ObjectNameInvalid
307→	}
308→	if dst == open.Path {
309→		// 改名到自己：直接成功，别去动文件系统。
310→		return nil
311→	}
312→
313→	fs := ctx.Tree.FS()
314→	if fs == nil {
315→		return status.NetworkNameDeleted
316→	}
317→	if err := fs.Rename(open.Path, dst, info.ReplaceIfExists); err != nil {
318→		return status.FromVFSError(err)
319→	}
320→
321→	// 句柄在改名后仍然有效，后续 QUERY_INFO 要能回新路径。
322→	open.Path = dst
323→	return nil
324→}
325→
326→// renameTarget 把线格式的目标名规范化成共享内相对路径。
327→//
328→// 线格式用反斜杠分隔、相对共享根、不含前导反斜杠（但真实客户端会带，
329→// 所以要容忍）。规范化与越界校验交给 vfs.CleanPath（AGENTS.md §8）。
330→func renameTarget(name string) (string, error) {
331→	name = strings.ReplaceAll(name, "\\", "/")
332→	name = strings.TrimPrefix(name, "/")
333→	if strings.IndexByte(name, ':') >= 0 {
334→		// 带 stream 名的改名（重命名 ADS）我们不支持，拒绝而不是误删主流。
335→		return "", vfs.ErrNotSupported
336→	}
337→	return vfs.CleanPath(name)
338→}
