  1→package command
  2→
  3→import (
  4→	"errors"
  5→
  6→	"github.com/finalappstore/stupidsamba/internal/smb/dialect"
  7→	"github.com/finalappstore/stupidsamba/internal/smb/status"
  8→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
  9→)
 10→
 11→func init() {
 12→	// IOCTL 不要求树连接：FSCTL_VALIDATE_NEGOTIATE_INFO 与
 13→	// FSCTL_DFS_GET_REFERRALS 都可能在没有有效 TreeId 时到达。
 14→	register(wire.CommandIoctl, true, false, handleIoctl)
 15→}
 16→
 17→// handleIoctl 处理 SMB2 IOCTL（MS-SMB2 §3.3.5.15）。
 18→//
 19→// 认不出的控制码一律回 STATUS_INVALID_DEVICE_REQUEST —— 这是 Windows 的行为，
 20→// 客户端会据此优雅退化。回 NOT_SUPPORTED 有些客户端会重试到超时。
 21→func handleIoctl(ctx *Context) error {
 22→	req, err := wire.ParseIoctlRequest(ctx.Msg)
 23→	if err != nil {
 24→		return status.InvalidParameter
 25→	}
 26→	if !req.IsFSCTL() {
 27→		// 我们不提供任何设备 IOCTL，只提供文件系统控制码。
 28→		return status.InvalidDeviceRequest
 29→	}
 30→
 31→	switch req.CtlCode {
 32→	case wire.FSCTLValidateNegotiateInfo:
 33→		return ioctlValidateNegotiate(ctx, req)
 34→	case wire.FSCTLPipeTransceive:
 35→		return ioctlPipeTransceive(ctx, req)
 36→	case wire.FSCTLQueryNetworkInterface:
 37→		// 不宣告多通道（我们不支持 SMB3 multichannel），
 38→		// 回空表示「没有额外接口」比回错误更让客户端满意。
 39→		return ioctlEmptyOK(ctx, req)
 40→	default:
 41→		ctx.Log.Debug("未实现的 FSCTL", "ctl", req.CtlCode)
 42→		return status.InvalidDeviceRequest
 43→	}
 44→}
 45→
 46→// ioctlValidateNegotiate 处理 FSCTL_VALIDATE_NEGOTIATE_INFO（MS-SMB2 §3.3.5.15.12）。
 47→//
 48→// ⚠️ 这是防降级攻击的复核：客户端把它**当初发出的** NEGOTIATE 请求内容
 49→// 再发一遍，要求服务端回显自己**当初响应过的**方言/能力/GUID/安全模式。
 50→// 任何字段对不上，Windows 会立刻 TCP RESET，且不给任何提示。
 51→//
 52→// 只在 3.0 / 3.0.2 上有意义：3.1.1 用 preauth integrity hash 覆盖了同样的
 53→// 威胁模型，客户端不会再发这个（MS-SMB2 §3.3.5.15.12 明确要求
 54→// 3.1.1 时回 STATUS_FILE_CLOSED）。
 55→func ioctlValidateNegotiate(ctx *Context, req *wire.IoctlRequest) error {
 56→	c := ctx.Conn
 57→
 58→	if c.Dialect == dialect.SMB311 {
 59→		// 规范要求的行为：3.1.1 上收到它说明对端行为异常。
 60→		return status.FileClosed
 61→	}
 62→	if c.Dialect < dialect.SMB300 {
 63→		return status.FileClosed
 64→	}
 65→
 66→	in, err := wire.ParseValidateNegotiateInfoRequest(req.Input)
 67→	if err != nil {
 68→		// 输入畸形也按「校验失败」处理：断连比放行降级攻击安全。
 69→		ctx.Log.Warn("VALIDATE_NEGOTIATE_INFO 输入畸形", "err", err)
 70→		return status.AccessDenied
 71→	}
 72→
 73→	// 复核客户端重放的内容与它当初 NEGOTIATE 时说的一致。
 74→	// 不一致说明中间有人改过报文（MS-SMB2 §3.3.5.15.12）。
 75→	if in.ClientGUID != c.ClientGUID ||
 76→		in.SecurityMode != c.ClientSecurityMode ||
 77→		in.Capabilities != c.ClientCapabilities ||
 78→		!sameDialects(in.Dialects, c.ClientDialects) {
 79→		ctx.Log.Warn("VALIDATE_NEGOTIATE_INFO 校验失败，疑似降级攻击",
 80→			"remote", c.RemoteAddr)
 81→		return status.AccessDenied
 82→	}
 83→
 84→	resp := &wire.ValidateNegotiateInfoResponse{
 85→		Capabilities: c.ServerCapabilities,
 86→		ServerGUID:   c.Settings.ServerGUID,
 87→		SecurityMode: c.ServerSecurityMode,
 88→		Dialect:      wire.Dialect(c.Dialect),
 89→	}
 90→	return appendIoctlResponse(ctx, req, resp.Encode())
 91→}
 92→
 93→// ioctlPipeTransceive 处理 FSCTL_PIPE_TRANSCEIVE（MS-SMB2 §3.3.5.15.10）：
 94→// 在一次往返里完成命名管道的写+读。这是现代客户端做 DCERPC 调用的默认方式。
 95→func ioctlPipeTransceive(ctx *Context, req *wire.IoctlRequest) error {
 96→	open, err := ctx.resolveOpen(req.FileID)
 97→	if err != nil {
 98→		return err
 99→	}
100→	if !open.IsPipe() {
101→		return status.InvalidDeviceRequest
102→	}
103→	if len(req.Input) == 0 {
104→		return status.InvalidParameter
105→	}
106→
107→	maxOut := int(req.MaxOutputResponse)
108→	if maxOut <= 0 {
109→		return status.InvalidParameter
110→	}
111→	// 上限同时受协商出的 MaxTransactSize 约束（AGENTS.md §8 资源上限）。
112→	if maxOut > int(ctx.Conn.MaxTransactSize) {
113→		maxOut = int(ctx.Conn.MaxTransactSize)
114→	}
115→
116→	terr := open.PipeTransact(req.Input, maxOut)
117→	if terr != nil && !errors.Is(terr, ErrPipeMoreData) {
118→		ctx.Log.Warn("命名管道 transceive 失败", "pipe", open.Path, "err", terr)
119→		return status.FromVFSError(terr)
120→	}
121→
122→	data := open.PipeRead(maxOut)
123→	if err := appendIoctlResponse(ctx, req, data); err != nil {
124→		return err
125→	}
126→	if open.PipePending() > 0 {
127→		// 响应没吐完：BUFFER_OVERFLOW 通知客户端继续 READ。
128→		ctx.Status = status.BufferOverflow
129→	}
130→	return nil
131→}
132→
133→// ioctlEmptyOK 回一个成功但输出为空的 IOCTL 响应。
134→func ioctlEmptyOK(ctx *Context, req *wire.IoctlRequest) error {
135→	return appendIoctlResponse(ctx, req, nil)
136→}
137→
138→// appendIoctlResponse 组装并追加 IOCTL Response。
139→func appendIoctlResponse(ctx *Context, req *wire.IoctlRequest, output []byte) error {
140→	if uint32(len(output)) > req.MaxOutputResponse {
141→		return status.BufferTooSmall
142→	}
143→	resp := &wire.IoctlResponse{
144→		CtlCode: req.CtlCode,
145→		FileID:  req.FileID,
146→		Flags:   req.Flags,
147→		Output:  output,
148→	}
149→	out, err := resp.Append(ctx.Out)
150→	if err != nil {
151→		ctx.Log.Error("编码 IOCTL Response 失败", "ctl", req.CtlCode, "err", err)
152→		return status.InsuffServerResources
153→	}
154→	ctx.Out = out
155→	return nil
156→}
157→
158→// sameDialects 比较两个方言列表是否完全一致（顺序敏感）。
159→//
160→// 顺序敏感是有意的：VALIDATE_NEGOTIATE_INFO 的意义就是逐字节复核客户端
161→// 当初发过的内容，放松成集合比较会给攻击者留下重排的空间。
162→func sameDialects(a []wire.Dialect, b []dialect.Dialect) bool {
163→	if len(a) != len(b) {
164→		return false
165→	}
166→	for i := range a {
167→		if uint16(a[i]) != uint16(b[i]) {
168→			return false
169→		}
170→	}
171→	return true
172→}
173→

