	// StatFS 返回卷级信息。
	StatFS() (*FSInfo, error)

	// Streams 列出某个对象的 alternate data stream。
	// 不支持时返回 ErrNotSupported。
	Streams(path string) ([]StreamInfo, error)

	// ReadOnly 表示本共享是否只读。只读时所有写操作应返回 ErrReadOnly。
	ReadOnly() bool

	// Close 释放文件系统级资源。
	Close() error
}

